code.java:
public long handshake(int n) {
    long count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {   // each unordered pair once
            count++;
        }
    }
    return count;
}

code.python:
def handshake(n: int) -> int:
    count = 0
    for i in range(n):
        for j in range(i + 1, n):           # each unordered pair once
            count += 1
    return count

